     1	/**
     2	 * Password-reset tokens.
     3	 *
     4	 * Private to the repository layer and absent from `corpus-manifest.json`: the
     5	 * `password_reset_tokens` table exists in the frozen schema but no manifest
     6	 * entry owns it, and `AuthService` cannot implement a real reset flow without
     7	 * somewhere to keep the single-use token.
     8	 */
     9	import { and, eq, gt } from "drizzle-orm";
    10	import { newId } from "@/lib/id";
    11	import { getDb, passwordResetTokens } from "@/server/db";
    12	import { toIsoTimestamp } from "@/types/common";
    13	import { brandId } from "./_mappers";
    14	import type { IsoTimestamp, UserId } from "@/types/common";
    15	
    16	export interface ResetToken {
    17	  readonly id: string;
    18	  readonly userId: UserId;
    19	  readonly expiresAt: IsoTimestamp;
    20	}
    21	
    22	export async function issueResetToken(
    23	  userId: UserId,
    24	  tokenHash: string,
    25	  expiresAt: IsoTimestamp,
    26	): Promise<ResetToken> {
    27	  const stamp = toIsoTimestamp(new Date());
    28	  const row = getDb()
    29	    .insert(passwordResetTokens)
    30	    .values({
    31	      id: newId(),
    32	      userId,
    33	      tokenHash,
    34	      expiresAt,
    35	      usedAt: null,
    36	      createdAt: stamp,
    37	      updatedAt: stamp,
    38	    })
    39	    .returning()
    40	    .get();
    41	
    42	  return {
    43	    id: row.id,
    44	    userId: brandId<UserId>(row.userId),
    45	    expiresAt: toIsoTimestamp(row.expiresAt),
    46	  };
    47	}
    48	
    49	/**
    50	 * Returns the token only while it is unexpired. Consuming a token retires it
    51	 * through `consumeResetToken`, so the used marker needs no second check here.
    52	 */
    53	export async function findLiveResetToken(
    54	  tokenHash: string,
    55	): Promise<ResetToken | null> {
    56	  const row = getDb()
    57	    .select()
    58	    .from(passwordResetTokens)
    59	    .where(
    60	      and(
    61	        eq(passwordResetTokens.tokenHash, tokenHash),
    62	        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
    63	      ),
    64	    )
    65	    .get();
    66	
    67	  if (!row) return null;
    68	
    69	  return {
    70	    id: row.id,
    71	    userId: brandId<UserId>(row.userId),
    72	    expiresAt: toIsoTimestamp(row.expiresAt),
    73	  };
    74	}
    75	
    76	/** Single use: consuming a token is what stops a reset link being replayed. */
    77	export async function consumeResetToken(id: string): Promise<void> {
    78	  const stamp = toIsoTimestamp(new Date());
    79	  getDb()
    80	    .update(passwordResetTokens)
    81	    .set({ usedAt: stamp, updatedAt: stamp })
    82	    .where(eq(passwordResetTokens.id, id))
    83	    .run();
    84	}
