67	    orgId: org.id,
68	    role: member.role,
69	  };
70	
71	  assertOrgScope(actor, org.id);
72	
73	  await memberRepo.touchLastSeen(
74	    org.id,
75	    principal.userId,
76	    toIsoTimestamp(new Date()),
77	  );
