    text: String(props.token ?? ""),
  }),
  sendEmail: async (message: { to: string; text: string }) => {
    outbox.push({ to: message.to, token: message.text });
  },
}));

import { getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import { hashPassword } from "@/lib/hash";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import {
  confirmPasswordReset,
  login,
  requestPasswordReset,
} from "@/server/services/auth-service";
import {
  createSessionToken,
  destroySession,
  resolveSession,
} from "@/server/services/session-service";
import { useTemporaryDatabase } from "../server/_support/fixtures";

const HOUR = 60 * 60 * 1000;
const PASSWORD = "Correct1Horse2";
const NEW_PASSWORD = "Another2Horse3";

let cleanup: () => void;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
  outbox.length = 0;
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

async function makeUser(email = `user${(counter += 1)}@auth.test`) {
  const user = await userRepo.insertUser({
    email,
    name: "Test User",
    passwordHash: await hashPassword(PASSWORD),
  });
  return { user, email };
}

function credentials(email: string, password = PASSWORD, rememberMe = false) {
  return { email, password, rememberMe };
}

async function tokenFor(email: string) {
  const mail = outbox.filter((message) => message.to === email).at(-1);
  if (!mail) throw new Error(`no reset mail for ${email}`);
  return mail.token;
}

function resetInput(token: string, password = NEW_PASSWORD) {
  return { token, password, confirmPassword: password };
}

describe("services/auth-service sessions", () => {
  it("signing out ends only that session", async () => {
    const { user, email } = await makeUser();
    const other = await makeUser();
    const laptop = await login(credentials(email));
    const phone = await login(credentials(email));
    const bystander = await createSessionToken(other.user.id);

    await destroySession(laptop.token);

    expect(await resolveSession(laptop.token)).toBeNull();
    expect((await resolveSession(phone.token))?.userId).toBe(user.id);
    expect(await resolveSession(bystander.token)).not.toBeNull();
  });

  it("signing out an unknown or ended session is harmless", async () => {
    const { email } = await makeUser();
    const first = await login(credentials(email));

    await destroySession("not-a-session-token");
    await destroySession(first.token);
    await destroySession(first.token);

    const second = await login(credentials(email));
    expect(second.token).not.toBe(first.token);
    expect(await resolveSession(second.token)).not.toBeNull();
  });

  it("lasts 24 hours without remember-me and 30 days with it", async () => {
    const { email } = await makeUser();
    const short = await login(credentials(email));
    const long = await login(credentials(email, PASSWORD, true));

    vi.setSystemTime(Date.now() + 23 * HOUR);
    expect(await resolveSession(short.token)).not.toBeNull();

    vi.setSystemTime(Date.now() + 2 * HOUR);
    expect(await resolveSession(short.token)).toBeNull();
    expect(await resolveSession(long.token)).not.toBeNull();

    vi.setSystemTime(Date.now() + 30 * 24 * HOUR);
    expect(await resolveSession(long.token)).toBeNull();
  });

  it("purges only expired sessions", async () => {
    const { user, email } = await makeUser();
    const short = await login(credentials(email));
    const long = await login(credentials(email, PASSWORD, true));

    vi.setSystemTime(Date.now() + 25 * HOUR);
    expect(await sessionRepo.purgeExpiredSessions(new Date().toISOString() as never)).toBe(1);
    expect(await resolveSession(short.token)).toBeNull();
    expect((await resolveSession(long.token))?.userId).toBe(user.id);
  });
});

describe("services/auth-service password reset", () => {
  it("is usable for 60 minutes, and only once", async () => {
    const { email } = await makeUser();

    await requestPasswordReset({ email });
    const token = await tokenFor(email);
    vi.setSystemTime(Date.now() + 59 * 60_000);
    await confirmPasswordReset(resetInput(token));

    await expect(confirmPasswordReset(resetInput(token))).rejects.toThrow(
      /no longer valid/,
    );

    await requestPasswordReset({ email });
    const late = await tokenFor(email);
    vi.setSystemTime(Date.now() + 61 * 60_000);
    await expect(confirmPasswordReset(resetInput(late))).rejects.toThrow(
      /no longer valid/,
    );
  });

  it("a new link retires the earlier ones, for that account only", async () => {
    const { email } = await makeUser();
    const bystander = await makeUser();

    await requestPasswordReset({ email });
    const first = await tokenFor(email);
    await requestPasswordReset({ email: bystander.email });
    const theirs = await tokenFor(bystander.email);
    await requestPasswordReset({ email });
    const second = await tokenFor(email);

    await expect(confirmPasswordReset(resetInput(first))).rejects.toThrow();
    await confirmPasswordReset(resetInput(theirs));
    await confirmPasswordReset(resetInput(second));
  });

  it("ends every session of the account and nobody else's", async () => {
    const { email } = await makeUser();
    const bystander = await makeUser();
    const laptop = await login(credentials(email));
    const phone = await login(credentials(email));
    const theirs = await login(credentials(bystander.email));

    await requestPasswordReset({ email });
    await confirmPasswordReset(resetInput(await tokenFor(email)));

    expect(await resolveSession(laptop.token)).toBeNull();
    expect(await resolveSession(phone.token)).toBeNull();
    expect(await resolveSession(theirs.token)).not.toBeNull();

    await expect(login(credentials(email))).rejects.toThrow(/did not match/);
    await expect(login(credentials(email, NEW_PASSWORD))).resolves.toBeDefined();
  });

  it("completes silently for an unknown address and matches case-insensitively", async () => {
    const { email } = await makeUser("Mixed.Case@auth.test");

    await requestPasswordReset({ email: "nobody@auth.test" });
    expect(outbox).toHaveLength(0);

    await requestPasswordReset({ email: "MIXED.CASE@AUTH.TEST" });
    expect(outbox).toHaveLength(1);
    await expect(login(credentials(email.toUpperCase()))).resolves.toBeDefined();
  });
});

describe("services/auth-service throttling", () => {
  it("throttles one account without touching another", async () => {
    const victim = await makeUser();
    const other = await makeUser();
    const { capacity } = getBucketConfig("auth:login");

    for (let i = 0; i < capacity; i += 1) {
      await expect(
        login(credentials(victim.email, "Wrong1Password")),
      ).rejects.toThrow(/did not match/);
    }

    await expect(login(credentials(victim.email.toUpperCase()))).rejects.toThrow(
      /Too many/,
    );
    await expect(login(credentials(other.email))).resolves.toBeDefined();

    // A throttled account can still reset its password.
    await requestPasswordReset({ email: victim.email });
    await confirmPasswordReset(resetInput(await tokenFor(victim.email)));
  });

  it("recovers as the bucket refills", async () => {
    const { email } = await makeUser();
    const { capacity } = getBucketConfig("auth:login");
    for (let i = 0; i < capacity; i += 1) {
      await login(credentials(email, "Wrong1Password")).catch(() => undefined);
    }
    await expect(login(credentials(email))).rejects.toThrow(/Too many/);

    vi.setSystemTime(Date.now() + 60_000);
    await expect(login(credentials(email))).resolves.toBeDefined();
  });

  it("limits reset requests per address, apart from sign-in attempts", async () => {
    const noisy = await makeUser();
    const quiet = await makeUser();
    const { capacity } = getBucketConfig("auth:password-reset");

    for (let i = 0; i < capacity + 3; i += 1) {
      await requestPasswordReset({ email: noisy.email });
    }
    expect(outbox.filter((m) => m.to === noisy.email)).toHaveLength(capacity);

    await requestPasswordReset({ email: quiet.email });
    expect(outbox.filter((m) => m.to === quiet.email)).toHaveLength(1);

    // Sign-in attempts on the noisy address are unaffected by its reset limit.
    await expect(login(credentials(noisy.email))).resolves.toBeDefined();
  });
});

